{"command":"cat >> fselect.py <<'PYEOF'

# ==================== Expression Nodes ====================
class Expr:
    pass

class ColRef(Expr):
    def __init__(self, name, alias=None):
        self.name=name  # canonical column name
        self.alias=alias  # for correlated subqueries? e.g., "data.name" where data is alias
        self.orig=name
    def __repr__(self):
        return f"Col({self.alias+'.' if self.alias else ''}{self.name})"

class StrLit(Expr):
    def __init__(self, val):
        self.val=val
    def __repr__(self):
        return f"Str({self.val!r})"

class NumLit(Expr):
    def __init__(self, val):
        self.val=val
    def __repr__(self):
        return f"Num({self.val})"

class FuncCall(Expr):
    def __init__(self, name, args):
        self.name=name
        self.args=args
    def __repr__(self):
        return f"Func({self.name},{self.args})"

class BinOp(Expr):
    def __init__(self, op, left, right):
        self.op=op
        self.left=left
        self.right=right
    def __repr__(self):
        return f"Bin({self.op},{self.left},{self.right})"

class UnOp(Expr):
    def __init__(self, op, expr):
        self.op=op
        self.expr=expr
    def __repr__(self):
        return f"Un({self.op},{self.expr})"

class Star(Expr):
    def __repr__(self):
        return "Star"

# For WHERE conditions, we use Expr tree with comparison ops, AND/OR/NOT, BETWEEN, IN, EXISTS, LIKE, REGEXP, etc.
# We'll represent comparisons as BinOp with op like '=', '!=', '>', etc., and special nodes for BETWEEN, IN, EXISTS.

class BetweenOp(Expr):
    def __init__(self, expr, low, high, neg=False):
        self.expr=expr; self.low=low; self.high=high; self.neg=neg

class InOp(Expr):
    def __init__(self, expr, values=None, subquery=None, neg=False):
        self.expr=expr; self.values=values; self.subquery=subquery; self.neg=neg

class ExistsOp(Expr):
    def __init__(self, subquery, neg=False):
        self.subquery=subquery; self.neg=neg

class LikeOp(Expr):
    def __init__(self, expr, pattern, neg=False):
        self.expr=expr; self.pattern=pattern; self.neg=neg

class RegexOp(Expr):
    def __init__(self, expr, pattern, neg=False):
        self.expr=expr; self.pattern=pattern; self.neg=neg

# Query structure
class Query:
    def __init__(self):
        self.select=[]  # list of Expr
        self.roots=[]  # list of Root
        self.where=None
        self.group_by=[]  # list of Expr or ColRef or position?
        self.order_by=[]  # list of (Expr/ColRef/pos, dir)
        self.limit=None
        self.offset=None
        self.into="tabs"

class Root:
    def __init__(self, path):
        self.path=path
        self.mindepth=None
        self.maxdepth=None
        self.follow_symlinks=False
        self.archives=False
        self.gitignore=None  # None=default from config, True/False override
        self.hgignore=None
        self.dockerignore=None
        self.dfs=False  # False=BFS default, True=DFS
        self.regexp=False
        self.alias=None

PYEOF
echo ok
