def contains_aggregate(e):
    if isinstance(e, FuncCall):
        if e.name in AGG_FUNCS:
            return True
        for a in e.args:
            if contains_aggregate(a):
                return True
        return False
    elif isinstance(e, BinOp):
        return contains_aggregate(e.left) or contains_aggregate(e.right)
    elif isinstance(e, UnOp):
        return contains_aggregate(e.expr)
    elif isinstance(e, BetweenOp):
        return contains_aggregate(e.expr) or contains_aggregate(e.low) or contains_aggregate(e.high)
    elif isinstance(e, InOp):
        if contains_aggregate(e.expr):
            return True
        if e.values:
            for v in e.values:
                if contains_aggregate(v):
                    return True
        # subquery aggregates? Subquery SELECT may contain aggregates, but that's inner, not outer. For outer SELECT aggregate detection, ignore subquery inner? Actually outer SELECT with IN subquery that has aggregates – outer itself not aggregate (unless outer expr has aggregates). So ignore subquery.
