def expr_equals(a,b):
    # Structural equality for GROUP BY matching (ColRef with same name/alias? FuncCall same? etc.)
    # Simplify: compare repr? Or compare type+values? For ColRef("ext") vs ColRef("ext") (same canonical, alias None or same alias?) -> True.
    # For "ext" vs "extension" (aliases to same canonical "ext")? Both canonical "ext", so True (since we canonicalize on parse). Good.
    # For FuncCall("upper", [ColRef("name")]) vs same -> True.
    # For BinOp, etc. – compare recursively.
    # For StrLit/NumLit – compare values.
    # For Star – True if both Star.
    if type(a)!=type(b):
        return False
    if isinstance(a, ColRef):
        return a.name==b.name and (a.alias or "").lower()==(b.alias or "").lower()
    elif isinstance(a, StrLit):
        return a.val==b.val
    elif isinstance(a, NumLit):
        return a.val==b.val
    elif isinstance(a, Star):
        return True
    elif isinstance(a, FuncCall):
        if a.name!=b.name or len(a.args)!=len(b.args):
            return False
        return all(expr_equals(x,y) for x,y in zip(a.args,b.args))
    elif isinstance(a, BinOp):
        return a.op==b.op and expr_equals(a.left,b.left) and expr_equals(a.right,b.right)
    elif isinstance(a, UnOp):
        return a.op==b.op and expr_equals(a.expr,b.expr)
    else:
        return False

